	if _, err := s.RegisterDevice("dev-3"); err != nil {
		t.Fatal(err)
	}
	stats, err = s.ListDevicePendingChanges("dev-3", 100, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(stats) != 0 {
		t.Fatalf("empty stats = %+v", stats)
	}
